namespace sv_777d35e9f69247c2af498b356c44d235.Services;

public class DoctorInfo
{
    public string Name { get; set; } = "";
    public bool AcceptsSelfPay { get; set; }
}

public interface IAppointmentService
{
    Task<List<DoctorInfo>> GetDoctorsAsync();
    Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date);
    Task<Dictionary<string, List<string>>> ValidatePatientAsync(
        string email, string insuranceProvider, string doctor, string timeSlot);
}

public class AppointmentService : IAppointmentService
{
    private static readonly List<DoctorInfo> Doctors =
    [
        new() { Name = "Dr. Smith", AcceptsSelfPay = false },
        new() { Name = "Dr. Johnson", AcceptsSelfPay = true },
        new() { Name = "Dr. Patel", AcceptsSelfPay = true },
        new() { Name = "Dr. Williams", AcceptsSelfPay = false },
    ];

    private static readonly List<string> AllSlots =
    [
        "9:00 AM", "9:30 AM", "10:00 AM", "10:30 AM",
        "11:00 AM", "11:30 AM", "1:00 PM", "1:30 PM",
        "2:00 PM", "2:30 PM", "3:00 PM", "3:30 PM",
    ];

    public Task<List<DoctorInfo>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<DoctorInfo>(Doctors));
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        // Return all slots for the stub; the "taken" check happens in ValidatePatientAsync.
        return Task.FromResult(new List<string>(AllSlots));
    }

    public Task<Dictionary<string, List<string>>> ValidatePatientAsync(
        string email, string insuranceProvider, string doctor, string timeSlot)
    {
        var errors = new Dictionary<string, List<string>>();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(BookAppointmentModel.Email)] = ["Account has outstanding balance"];
        }

        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            errors[nameof(BookAppointmentModel.Doctor)] = ["Selected doctor does not accept self-pay patients"];
        }

        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors[nameof(BookAppointmentModel.TimeSlot)] = ["This slot is no longer available"];
        }

        return Task.FromResult(errors);
    }
}

public class BookAppointmentModel
{
    public string? Name { get; set; }
    public string? Email { get; set; }
    public string? Phone { get; set; }
    public string InsuranceProvider { get; set; } = "";
    public string? Doctor { get; set; }
    public DateOnly? AppointmentDate { get; set; }
    public string? TimeSlot { get; set; }
    public string? Reason { get; set; }
}

using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Forms;

namespace sv_777d35e9f69247c2af498b356c44d235.Components;

public class CustomValidator : ComponentBase
{
    [CascadingParameter]
    private EditContext? EditContext { get; set; }

    private ValidationMessageStore? messageStore;

    protected override void OnInitialized()
    {
        messageStore = new ValidationMessageStore(EditContext!);
        EditContext!.OnValidationRequested += (s, e) => messageStore.Clear();
        EditContext!.OnFieldChanged += (s, e) => messageStore.Clear(e.FieldIdentifier);
    }

    public void DisplayErrors(Dictionary<string, List<string>> errors)
    {
        foreach (var (field, messages) in errors)
        {
            foreach (var message in messages)
            {
                messageStore!.Add(EditContext!.Field(field), message);
            }
        }
        EditContext!.NotifyValidationStateChanged();
    }

    public void ClearErrors()
    {
        messageStore?.Clear();
        EditContext?.NotifyValidationStateChanged();
    }
}

