@page "/book-appointment"
@using sv_777d35e9f69247c2af498b356c44d235.Services
@using System.ComponentModel.DataAnnotations
@inject IAppointmentService AppointmentService
@rendermode InteractiveServer

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book an Appointment</h3>

<EditForm EditContext="editContext" OnSubmit="HandleSubmit">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    @* ───── STEP 1 ───── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="model.Name" />
            <ValidationMessage For="() => model.Name" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="model.Email" />
            <ValidationMessage For="() => model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="model.Phone" />
            <ValidationMessage For="() => model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Continue
            </button>
        }
    </fieldset>

    @* ───── STEP 2 ───── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="model.Doctor"
                             @bind:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc.Name">
                            @doc.Name @(doc.AcceptsSelfPay ? "" : "(no self-pay)")
                        </option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.Doctor" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="model.AppointmentDate"
                           @bind:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeslot">Time Slot</label>
                <InputSelect id="timeslot" class="form-select" @bind-Value="model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="model.Reason" />
                <ValidationMessage For="() => model.Reason" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">Back</button>
            <button type="submit" class="btn btn-success" disabled="@isSubmitting">
                @(isSubmitting ? "Checking..." : "Check Availability")
            </button>
        </fieldset>
    }
</EditForm>

@if (submitted)
{
    <div class="alert alert-success mt-4">
        Appointment request submitted successfully!
    </div>
}

@code {
    private AppointmentFormModel model = new();
    private EditContext editContext = default!;
    private CustomValidator? customValidator;

    private List<DoctorInfo> doctors = [];
    private List<string> timeSlots = [];

    private bool showStep2;
    private bool isSubmitting;
    private bool submitted;

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only step-1 fields manually.
        customValidator?.ClearErrors();
        var step1Valid = true;
        var store = new ValidationMessageStore(editContext);

        if (string.IsNullOrWhiteSpace(model.Name))
        {
            store.Add(editContext.Field(nameof(model.Name)), "Patient name is required.");
            step1Valid = false;
        }
        if (string.IsNullOrWhiteSpace(model.Email))
        {
            store.Add(editContext.Field(nameof(model.Email)), "Email is required.");
            step1Valid = false;
        }
        else if (!new EmailAddressAttribute().IsValid(model.Email))
        {
            store.Add(editContext.Field(nameof(model.Email)), "Invalid email format.");
            step1Valid = false;
        }
        if (string.IsNullOrWhiteSpace(model.Phone))
        {
            store.Add(editContext.Field(nameof(model.Phone)), "Phone is required.");
            step1Valid = false;
        }
        if (string.IsNullOrWhiteSpace(model.InsuranceProvider))
        {
            store.Add(editContext.Field(nameof(model.InsuranceProvider)), "Insurance provider is required.");
            step1Valid = false;
        }

        editContext.NotifyValidationStateChanged();

        if (step1Valid)
        {
            store.Clear();
            editContext.NotifyValidationStateChanged();
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
    }

    private async Task OnDoctorOrDateChanged()
    {
        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                model.Doctor, model.AppointmentDate.Value);
            model.TimeSlot = null;
        }
    }

    private async Task HandleSubmit()
    {
        customValidator?.ClearErrors();

        if (!editContext.Validate())
            return;

        isSubmitting = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                model.Email!, model.InsuranceProvider, model.Doctor!, model.TimeSlot!);

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                return;
            }

            submitted = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    // Nested model with data annotations for step-2 validation via DataAnnotationsValidator.
    private class AppointmentFormModel
    {
        [Required(ErrorMessage = "Patient name is required.")]
        public string? Name { get; set; }

        [Required(ErrorMessage = "Email is required.")]
        [EmailAddress(ErrorMessage = "Invalid email format.")]
        public string? Email { get; set; }

        [Required(ErrorMessage = "Phone is required.")]
        public string? Phone { get; set; }

        [Required(ErrorMessage = "Insurance provider is required.")]
        public string InsuranceProvider { get; set; } = "";

        [Required(ErrorMessage = "Please select a doctor.")]
        public string? Doctor { get; set; }

        [Required(ErrorMessage = "Please select a date.")]
        [FutureDate(ErrorMessage = "Date must be in the future.")]
        public DateOnly? AppointmentDate { get; set; }

        [Required(ErrorMessage = "Please select a time slot.")]
        public string? TimeSlot { get; set; }

        [Required(ErrorMessage = "Reason for visit is required.")]
        [MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters.")]
        public string? Reason { get; set; }
    }

    private class FutureDateAttribute : ValidationAttribute
    {
        public override bool IsValid(object? value)
        {
            if (value is DateOnly date)
                return date > DateOnly.FromDateTime(DateTime.Today);
            return false;
        }
    }
}

